export type CorpusArchetype =
  | "essay"
  | "literature_review"
  | "research_paper"
  | "case_study"
  | "report"
  | "critical_essay"
  | "argumentative_essay"
  | "policy_analysis"
  | "business_assignment"
  | "journal_article"
  | "presentation_slides";

export interface ArchetypeClassification {
  predictedArchetype: CorpusArchetype | AssignmentType;
  confidence: number;
  classProbabilities: Record<string, number>;
  primaryTone: string;
  secondaryTone: string;
  recommendedTone: AcademicTone;
  stylisticProfile: {
    avgSentenceLength: number;
    sentenceLengthStd: number;
    avgWordLength: number;
    typeTokenRatio: number;
    passiveVoiceRatio: number;
    citationDensity: number;
  };
}

export interface StyleAuditReport {
  isCompliant: boolean;
  overallScore: number; // 0 - 100
  predictedArchetype: CorpusArchetype | AssignmentType;
  targetArchetype: CorpusArchetype | AssignmentType;
  primaryTone: string;
  secondaryTone: string;
  metrics: {
    avgSentenceLength: number;
    targetSentenceLengthRange: [number, number];
    passiveVoiceRatio: number;
    targetPassiveVoiceMax: number;
    lexicalDiversity: number;
    targetLexicalDiversityMin: number;
    citationDensity: number;
    targetCitationDensityMin: number;
  };
  recommendations: string[];
}

