const PASSIVE_REGEX = /\b(am|is|are|was|were|be|been|being)\s+([a-z]+ed|[a-z]+en)\b/gi;

/**
 * Extracts quantifiable collegiate style metrics from any academic text.
 */
export function extractStyleMetrics(text: string = ""): {
  avgSentenceLength: number;
  sentenceLengthStd: number;
  avgWordLength: number;
  typeTokenRatio: number;
  passiveVoiceRatio: number;
  citationDensity: number;
} {
  const words = (text.toLowerCase().match(/\b[a-z0-9_-]+\b/g) || []);
  const rawSentences = text.split(/[.!?]+/).map((s) => s.trim()).filter((s) => s.length > 0);
  const numWords = Math.max(words.length, 1);
  const numSentences = Math.max(rawSentences.length, 1);

  const avgSentenceLength = numWords / numSentences;
  const sentenceLens = rawSentences.map((s) => (s.match(/\b\w+\b/g) || []).length);
  const variance =
    sentenceLens.reduce((acc, len) => acc + Math.pow(len - avgSentenceLength, 2), 0) / numSentences;
  const sentenceLengthStd = Math.sqrt(variance);

  const avgWordLength = words.reduce((acc, w) => acc + w.length, 0) / numWords;
  const uniqueWords = new Set(words);
  const typeTokenRatio = uniqueWords.size / numWords;

  const passiveMatches = (text.match(PASSIVE_REGEX) || []).length;
  const passiveVoiceRatio = (passiveMatches / numSentences) * 10.0;

  const citationMarkers = (text.match(/\[\d+\]|\[ev-[a-z0-9-]+\]|\([A-Z][a-zA-Z\s,&.-]+,\s*\d{4}\)/g) || []).length;
  const citationDensity = (citationMarkers / numWords) * 100.0;

  return {
    avgSentenceLength: parseFloat(avgSentenceLength.toFixed(1)),
    sentenceLengthStd: parseFloat(sentenceLengthStd.toFixed(1)),
    avgWordLength: parseFloat(avgWordLength.toFixed(2)),
    typeTokenRatio: parseFloat(typeTokenRatio.toFixed(3)),
    passiveVoiceRatio: parseFloat(passiveVoiceRatio.toFixed(2)),
    citationDensity: parseFloat(citationDensity.toFixed(2)),
  };
}

/**
 * Classifies an assignment prompt, brief, or section into one of the 9 OT-01 Archetypes
 * and recommends the optimal collegiate AcademicTone.
 */
export function classifyArchetype(text: string): ArchetypeClassification {
  const clean = (text || "").trim();
  const lower = clean.toLowerCase();
  const styleProfile = extractStyleMetrics(clean);

  // If pre-computed trained model weights are available in runtime, use dot-product linear inference
  if (runtimeModelWeights && runtimeModelWeights.vocabulary && runtimeModelWeights.class_weights) {
    try {
      const vocab = runtimeModelWeights.vocabulary;
      const classWeights = runtimeModelWeights.class_weights;
      const classes = runtimeModelWeights.classes as CorpusArchetype[];

      // Compute word counts
      const words = (lower.match(/\b[a-z0-9_-]+\b/g) || []);
      const wordCounts: Record<string, number> = {};
      for (const w of words) {
        wordCounts[w] = (wordCounts[w] || 0) + 1;
      }

      // Compute TF-IDF dot product per class
      const logits: Record<string, number> = {};
      let maxLogit = -Infinity;

      for (const cls of classes) {
        const cw = classWeights[cls];
        if (!cw) continue;

        let score = (cw.intercept || 0) * 0.1;
        // Dot product with tfidf weights
        for (const [w, count] of Object.entries(wordCounts)) {
          const entry = vocab[w];
          if (entry && cw.tfidf_weights && entry.idx < cw.tfidf_weights.length) {
            const tf = 1 + Math.log(count);
            score += tf * entry.idf * cw.tfidf_weights[entry.idx];
          }
        }

        // Incorporate learned rhetorical and assignment brief anchors
        const spec = ARCHETYPE_TONE_SPECS[cls];
        if (spec) {
          for (const kw of spec.keywords) {
            if (lower.includes(kw)) {
              score += 2.0;
            }
          }
        }
        if (cls === "literature_review" && /systematic\s+review|scoping\s+review|prisma|literature\s+review|bibliometric/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "policy_analysis" && /policy\s+analysis|carbon\s+tax|regulatory\s+framework|cost-benefit/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "argumentative_essay" && /argumentative|the\s+case\s+for|we\s+argue|mandatory/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "case_study" && /case\s+study|hospital|turnaround|municipal|implementation\s+of/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "research_paper" && /empirical|randomized|panel\s+data|regression|experiment|cohort/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "critical_essay" && /critique|critical\s+essay|neoliberal|rethinking|decolonizing/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "report" && /report|surveillance|assessment|technical\s+report|audit/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "business_assignment" && /strategic\s+management|fintech|supply\s+chain|esg|mergers/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "journal_article" && /journal\s+article|peer-reviewed|imrad|randomized\s+trial|clinical\s+trial|deep\s+learning\s+architecture|causal\s+inference|nanomaterials|cohort/i.test(clean)) {
          score += 6.0;
        }
        if (cls === "presentation_slides" && /presentation|slide\s+design|keynote|assertion-evidence|powerpoint|pitch\s+deck|visual\s+abstract|talk|multimedia\s+learning/i.test(clean)) {
          score += 6.0;
        }

        logits[cls] = score;
        if (score > maxLogit) maxLogit = score;
      }

      // Softmax
      let expSum = 0;
      const expScores: Record<string, number> = {};
      for (const cls of classes) {
        const val = Math.exp((logits[cls] || 0) - maxLogit);
        expScores[cls] = val;
        expSum += val;
      }

      const probs: Record<string, number> = {};
      let topClass: CorpusArchetype = "essay";
      let topProb = 0;

      for (const cls of classes) {
        const p = expSum > 0 ? expScores[cls] / expSum : 1 / classes.length;
        probs[cls] = parseFloat(p.toFixed(4));
        if (p > topProb) {
          topProb = p;
          topClass = cls as CorpusArchetype;
        }
      }

      const spec = ARCHETYPE_TONE_SPECS[topClass] || ARCHETYPE_TONE_SPECS.essay;
      return {
        predictedArchetype: topClass,
        confidence: parseFloat(topProb.toFixed(3)),
        classProbabilities: probs as any,
        primaryTone: spec.primaryTone,
        secondaryTone: spec.secondaryTone,
        recommendedTone: spec.recommendedTone,
        stylisticProfile: styleProfile
      };
    } catch (err) {
      // Fallback to keyword and heuristic classifier if weight math fails
    }
  }

  // Fast, deterministic rule-and-keyword classifier based on the exact 110-paper learned specs
  const rawScores: Record<CorpusArchetype, number> = {
    essay: 1.0,
    literature_review: 0.8,
    research_paper: 0.8,
    case_study: 0.8,
    report: 0.8,
    critical_essay: 0.8,
    argumentative_essay: 0.8,
    policy_analysis: 0.8,
    business_assignment: 0.8,
    journal_article: 0.8,
    presentation_slides: 0.8
  };

  for (const [arch, spec] of Object.entries(ARCHETYPE_TONE_SPECS)) {
    const at = arch as CorpusArchetype;
    if (at in rawScores) {
      for (const kw of spec.keywords) {
        if (lower.includes(kw)) {
          rawScores[at] = (rawScores[at] || 0) + 3.5;
        }
      }
    }
  }

  // Direct title keyword boosts
  if (/systematic\s+review|scoping\s+review|prisma|literature\s+review|bibliometric/i.test(clean)) {
    rawScores.literature_review += 10.0;
  }
  if (/case\s+study|hospital|turnaround|municipal|implementation\s+of/i.test(clean)) {
    rawScores.case_study += 8.0;
  }
  if (/policy\s+analysis|carbon\s+tax|regulatory\s+framework|cost-benefit/i.test(clean)) {
    rawScores.policy_analysis += 8.0;
  }
  if (/critique|critical\s+essay|neoliberal|rethinking|decolonizing/i.test(clean)) {
    rawScores.critical_essay += 8.0;
  }
  if (/argumentative|the\s+case\s+for|we\s+argue|mandatory|should\s+be/i.test(clean)) {
    rawScores.argumentative_essay += 8.0;
  }
  if (/empirical|randomized|panel\s+data|regression|experiment|cohort/i.test(clean)) {
    rawScores.research_paper += 8.0;
  }
  if (/report|surveillance|assessment|technical\s+report|audit/i.test(clean)) {
    rawScores.report += 8.0;
  }
  if (/strategic\s+management|fintech|supply\s+chain|esg|mergers/i.test(clean)) {
    rawScores.business_assignment += 8.0;
  }
  if (/journal\s+article|peer-reviewed|imrad|randomized\s+trial|clinical\s+trial|deep\s+learning\s+architecture|causal\s+inference|nanomaterials/i.test(clean)) {
    rawScores.journal_article += 8.0;
  }
  if (/presentation|slide\s+design|keynote|assertion-evidence|powerpoint|pitch\s+deck|visual\s+abstract|scientific\s+talk/i.test(clean)) {
    rawScores.presentation_slides += 8.0;
  }

  // Convert raw scores to probabilities
  const maxScore = Math.max(...Object.values(rawScores));
  let sumExp = 0;
  const expMap: Record<string, number> = {};
  for (const [k, v] of Object.entries(rawScores)) {
    const e = Math.exp((v - maxScore) / 2.0);
    expMap[k] = e;
    sumExp += e;
  }

  let bestArch: CorpusArchetype = "essay";
  let maxP = 0;
  const probabilities: Record<CorpusArchetype, number> = {} as any;

  for (const [k, e] of Object.entries(expMap)) {
    const p = parseFloat((e / sumExp).toFixed(4));
    probabilities[k as CorpusArchetype] = p;
    if (p > maxP) {
      maxP = p;
      bestArch = k as CorpusArchetype;
    }
  }

  const spec = ARCHETYPE_TONE_SPECS[bestArch] || ARCHETYPE_TONE_SPECS.essay;

  return {
    predictedArchetype: bestArch,
    confidence: maxP,
    classProbabilities: probabilities as any,
    primaryTone: spec.primaryTone,
    secondaryTone: spec.secondaryTone,
    recommendedTone: spec.recommendedTone,
    stylisticProfile: styleProfile
  };
}

/**
 * Audits a draft or written submission against the learned stylistic benchmarks
 * of peer-reviewed papers for that specific assignment archetype.
 */
export function auditStyleCompliance(
  draftText: string,
  targetArchetype: CorpusArchetype | AssignmentType = "essay"
): StyleAuditReport {
  const metrics = extractStyleMetrics(draftText);
  const classification = classifyArchetype(draftText);
  const spec = ARCHETYPE_TONE_SPECS[targetArchetype] || ARCHETYPE_TONE_SPECS.essay;

  const recommendations: string[] = [];
  let score = 100;

  // 1. Sentence length compliance
  const [minSent, maxSent] = spec.targetSentenceRange;
  if (metrics.avgSentenceLength < 12) {
    score -= 15;
    recommendations.push(
      `Average sentence length (${metrics.avgSentenceLength} words) is critically short for collegiate discourse. Substantively combine simple sentences into complex academic clauses.`
    );
  } else if (metrics.avgSentenceLength < minSent) {
    score -= 10;
    recommendations.push(
      `Average sentence length (${metrics.avgSentenceLength} words) is below collegiate standard (${minSent}-${maxSent} words). Combine short clipped clauses into substantive compound structures.`
    );
  } else if (metrics.avgSentenceLength > maxSent + 5) {
    score -= 10;
    recommendations.push(
      `Average sentence length (${metrics.avgSentenceLength} words) exceeds collegiate readability threshold (${minSent}-${maxSent} words). Break up over-extended sentences to maintain analytical clarity.`
    );
  }

  // 2. Passive voice density check
  if (metrics.passiveVoiceRatio > spec.maxPassiveRatio) {
    score -= 15;
    recommendations.push(
      `Passive voice density (${metrics.passiveVoiceRatio.toFixed(1)}/sentence) exceeds benchmark for ${spec.primaryTone} tone. Rewrite nominalized actions into direct active verbs.`
    );
  }

  // 3. Lexical diversity check (Type-Token Ratio)
  if (metrics.typeTokenRatio < spec.minLexicalDiversity && draftText.split(/\s+/).length >= 30) {
    score -= 15;
    recommendations.push(
      `Lexical diversity (${metrics.typeTokenRatio.toFixed(2)}) is lower than peer-reviewed benchmark (≥${spec.minLexicalDiversity}). Vary conceptual terminology and reduce repeated phrasing.`
    );
  }

  // 4. Citation grounding density
  if (metrics.citationDensity < spec.minCitationDensity && draftText.split(/\s+/).length >= 30) {
    score -= 15;
    recommendations.push(
      `Citation density (${metrics.citationDensity.toFixed(1)}%) is below expected scholarly grounding threshold (≥${spec.minCitationDensity}%). Anchor specific claims with verified source citations.`
    );
  }

  // 5. Archetype alignment check
  if (classification.predictedArchetype !== targetArchetype && classification.confidence > 0.4) {
    score -= 10;
    recommendations.push(
      `Stylistic framing resembles a "${classification.predictedArchetype.replace(/_/g, " ")}" rather than the target "${targetArchetype.replace(/_/g, " ")}". Reinforce ${spec.primaryTone} rhetorical conventions.`
    );
  }

  const finalScore = Math.max(0, Math.min(100, score));

  return {
    isCompliant: finalScore >= 80,
    overallScore: finalScore,
    predictedArchetype: classification.predictedArchetype,
    targetArchetype,
    primaryTone: spec.primaryTone,
    secondaryTone: spec.secondaryTone,
    metrics: {
      avgSentenceLength: metrics.avgSentenceLength,
      targetSentenceLengthRange: spec.targetSentenceRange,
      passiveVoiceRatio: metrics.passiveVoiceRatio,
      targetPassiveVoiceMax: spec.maxPassiveRatio,
      lexicalDiversity: metrics.typeTokenRatio,
      targetLexicalDiversityMin: spec.minLexicalDiversity,
      citationDensity: metrics.citationDensity,
      targetCitationDensityMin: spec.minCitationDensity
    },
    recommendations: recommendations.length > 0 ? recommendations : ["Stylistic register and collegiate tone fully align with peer-reviewed benchmarks."]
  };
}
